source='''def transform(grid):
    """Extend each solid 3x3 colored block along its middle row and column."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                blocks.append((r + 1, c + 1, color))
    beams = {}
    for i, (r, c, color) in enumerate(blocks):
        for x in range(w):
            beams.setdefault((r, x), set()).add(i)
        for y in range(h):
            beams.setdefault((y, c), set()).add(i)
    for (r, c), ids in beams.items():
        out[r][c] = blocks[next(iter(ids))][2] if len(ids) == 1 else 0
    return out
